@pytest.mark.tc('TC_ASTORE_007')
def test_tc_astore_007_delete_order_returns_200_and_subsequent(api):
    """TC_ASTORE_007: Delete order returns 200 and subsequent GET returns 404

    Scenario: SC_ASTORE_007
    Endpoint: DELETE  store order {orderId}
    Expected: DELETE HTTP 200, then GET  store order {orderId} returns HTTP 404.
    """
    with api.step('Create order for deletion', method='POST', path='/store/order'):
        api.send(
            {'method': 'POST',
             'path': '/store/order',
             'headers': {'Content-Type': 'application/json'},
             'body': {'petId': 198773,
                      'quantity': 5,
                      'shipDate': '2024-01-16T10:30:00Z',
                      'status': 'placed',
                      'complete': False},
             'save': {'orderId': '$.id'},
             'expect': {'status': 200,
                        'headers': {'Content-Type': 'application/json'},
                        'json': [{'path': '$.id', 'op': 'exists'}],
                        'schema': {'type': 'object',
                                   'properties': {'id': {'type': 'integer', 'format': 'int64'},
                                                  'petId': {'type': 'integer', 'format': 'int64'},
                                                  'quantity': {'type': 'integer', 'format': 'int32'},
                                                  'shipDate': {'type': 'string', 'format': 'date-time'},
                                                  'status': {'type': 'string',
                                                             'enum': ['placed', 'approved', 'delivered']},
                                                  'complete': {'type': 'boolean'}},
                                   'required': ['id', 'petId', 'quantity', 'shipDate', 'status', 'complete']}}}
        )
    with api.step('Delete order', method='DELETE', path='/store/order/{orderId}'):
        api.send(
            {'method': 'DELETE',
             'path': '/store/order/{orderId}',
             'path_params': {'orderId': '{{var.orderId}}'},
             'expect': {'status': 200}}
        )
    with api.step('Verify order deleted', method='GET', path='/store/order/{orderId}'):
        api.send(
            {'method': 'GET',
             'path': '/store/order/{orderId}',
             'path_params': {'orderId': '{{var.orderId}}'},
             'headers': {'Accept': 'application/json'},
             'expect': {'status': 404}}
        )

@pytest.mark.tc('TC_ASTORE_008')
def test_tc_astore_008_order_crud_lifecycle_create_read_delete(api):
    """TC_ASTORE_008: Order CRUD lifecycle: create -> read -> delete -> read 404

    Scenario: SC_ASTORE_008
    Endpoint: POST  store order
    Expected: Each step returns documented success code; final GET returns 404.
    """
    with api.step('Create order', method='POST', path='/store/order'):
        api.send(
            {'method': 'POST',
             'path': '/store/order',
             'headers': {'Content-Type': 'application/json'},
             'body': {'id': 0,
                      'petId': '{{env:EXISTING_PET_ID}}',
                      'quantity': 2,
                      'shipDate': '{{env:SHIP_DATE}}',
                      'status': 'placed',
                      'complete': False},
             'save': {'order_id': '$.id',
                      'created_pet_id': '$.petId',
                      'created_quantity': '$.quantity',
                      'created_status': '$.status',
                      'created_complete': '$.complete'},
             'expect': {'status': 200,
                        'headers': {'Content-Type': 'application/json'},
                        'json': [{'path': '$.id', 'op': 'exists'},
                                 {'path': '$.petId', 'op': 'equals', 'value': '{{env:EXISTING_PET_ID}}'},
                                 {'path': '$.quantity', 'op': 'equals', 'value': 2},
                                 {'path': '$.status', 'op': 'equals', 'value': 'placed'},
                                 {'path': '$.complete', 'op': 'equals', 'value': False}],
                        'schema': {'type': 'object',
                                   'properties': {'id': {'type': 'integer', 'format': 'int64'},
                                                  'petId': {'type': 'integer', 'format': 'int64'},
                                                  'quantity': {'type': 'integer', 'format': 'int32'},
                                                  'shipDate': {'type': 'string', 'format': 'date-time'},
                                                  'status': {'type': 'string',
                                                             'enum': ['placed', 'approved', 'delivered']},
                                                  'complete': {'type': 'boolean'}},
                                   'required': ['id', 'petId', 'quantity', 'shipDate', 'status', 'complete']}}}
        )
    with api.step('Read order after create', method='GET', path='/store/order/{orderId}'):
        api.send(
            {'method': 'GET',
             'path': '/store/order/{orderId}',
             'path_params': {'orderId': '{{var.order_id}}'},
             'expect': {'status': 200,
                        'headers': {'Content-Type': 'application/json'},
                        'json': [{'path': '$.id', 'op': 'equals', 'value': '{{var.order_id}}'},
                                 {'path': '$.petId', 'op': 'equals', 'value': '{{var.created_pet_id}}'},
                                 {'path': '$.quantity', 'op': 'equals', 'value': '{{var.created_quantity}}'},
                                 {'path': '$.status', 'op': 'equals', 'value': '{{var.created_status}}'},
                                 {'path': '$.complete', 'op': 'equals', 'value': '{{var.created_complete}}'}],
                        'schema': {'type': 'object',
                                   'properties': {'id': {'type': 'integer', 'format': 'int64'},
                                                  'petId': {'type': 'integer', 'format': 'int64'},
                                                  'quantity': {'type': 'integer', 'format': 'int32'},
                                                  'shipDate': {'type': 'string', 'format': 'date-time'},
                                                  'status': {'type': 'string',
                                                             'enum': ['placed', 'approved', 'delivered']},
                                                  'complete': {'type': 'boolean'}},
                                   'required': ['id', 'petId', 'quantity', 'shipDate', 'status', 'complete']}}}
        )
    with api.step('Delete order', method='DELETE', path='/store/order/{orderId}'):
        api.send(
            {'method': 'DELETE',
             'path': '/store/order/{orderId}',
             'path_params': {'orderId': '{{var.order_id}}'},
             'expect': {'status': 200}}
        )
    with api.step('Verify order not found after delete', method='GET', path='/store/order/{orderId}'):
        api.send(
            {'method': 'GET',
             'path': '/store/order/{orderId}',
             'path_params': {'orderId': '{{var.order_id}}'},
             'expect': {'status': 404}}
        )

